1	package water
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	// 本文件保护“打开本地数据”时对已保存判定依据的时间核对：
13	// 带结论的样品（已确认，以及已确认后作废、逐项依据仍保留在 Results 中的样品），
14	// 每条逐项判定保存的上限生效时间必须存在且不晚于这份样品的采样时间——确认时只
15	// 选用采样当时已经生效的上限，保存下来的依据也必须遵守同一规则。limitEffective
16	// 字段缺失、保存为 null 或落盘为 Go 零时间都表示缺少生效依据，不能当成一版很早
17	// 的上限放行；生效时间晚于采样时间（按真实时刻比较，保留纳秒精度：恰好相等可以
18	// 接受，晚一纳秒也拒绝；不同时区写法表示同一时刻按相等处理）也必须整次拒绝，
19	// 即使测量值、上限数值与超标标记互相对得上。拒绝返回 nil 存放、错误可识别为
20	// ErrCorruptRecord 并点名样品编号与项目，区分“缺少生效时间”与“晚于采样时间”
21	// 两种信息，后者同时带出两处时间且保留足以说明先后的小数秒；原文件不变，不跳过
22	// 记录、不补填日期、不替换上限、不退回待判定、不重新计算结论。核对只针对样品自己
23	// 保存的依据：后来补录的采样之前生效的新上限不影响旧结论原样读入；没有逐项判定
24	// 的待判定样品与直接作废的样品照常打开。
25	
26	// assertOpenRejectsEffective 在 assertOpenRejects 的基础上进一步断言错误信息
27	// 包含（或不包含）特定片段，用于区分“缺少生效时间”与“晚于采样时间”两种拒绝。
28	func assertOpenRejectsEffective(t *testing.T, dir, sampleID, item string, contains, notContains []string) {
29		t.Helper()
30		assertOpenRejects(t, dir, sampleID, item, false)
31		// assertOpenRejects 已经重新打开过一次并断言失败；这里再开一次取错误信息。
32		// 它同时保证了原文件未被改动，因此再次打开得到的错误与第一次一致。
33		_, err := Open(dir)
34		if err == nil {
35			t.Fatalf("损坏数据必须让整次 Open 失败，sample=%s", sampleID)
36		}
37		// 只核对哨兵文本之后的具体原因部分：ErrCorruptRecord 的文案枚举了所有
38		// 损坏类型，两种生效时间问题的区分体现在各条错误的具体描述里。
39		msg := strings.TrimPrefix(err.Error(), ErrCorruptRecord.Error())
40		for _, want := range contains {
41			if !strings.Contains(msg, want) {
42				t.Fatalf("错误信息应包含 %q，实际 %q", want, msg)
43			}
44		}
45		for _, unwanted := range notContains {
46			if strings.Contains(msg, unwanted) {
47				t.Fatalf("错误信息不应包含 %q，实际 %q", unwanted, msg)
48			}
49		}
50	}
51	
52	// 任务示例：样品 9 月 10 日采样，保存的浊度上限却标明 9 月 11 日生效，即使测量值
53	// 4、上限 5 与达标标记互相对得上，也必须在打开时拒绝；错误点名样品与项目，说明
54	// 生效时间晚于采样时间并带出两处时间。
55	func TestOpenConfirmedLimitEffectiveAfterSampling(t *testing.T) {
56		dir := t.TempDir()
57		writeDiskFile(t, dir, diskState{
58			Points: openPoints(),
59			Samples: map[string]*Sample{
60				"S1": {
61					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
62					Measurements: []Measurement{{Item: openTurb, Value: 4}},
63					Status:       StatusConfirmed, Exceeded: false,
64					Results: []ItemResult{
65						{Item: openTurb, Value: 4, Limit: 5, LimitEffective: at(11, 0), Exceeded: false},
66					},
67				},
68			},
69		})
70		assertOpenRejectsEffective(t, dir, "S1", openTurb,
71			[]string{"晚于采样时间",
72				at(11, 0).Format(time.RFC3339Nano), at(10, 0).Format(time.RFC3339Nano)},
73			[]string{"缺少上限生效时间"})
74	}
75	
76	// 生效时间比采样时间晚一纳秒也必须拒绝：先后按真实时刻判断，保留纳秒精度；
77	// 错误信息中的两处时间必须带足以说明先后的小数秒。
78	func TestOpenLimitEffectiveOneNanosecondLate(t *testing.T) {
79		dir := t.TempDir()
80		sampled := time.Date(2026, 9, 10, 12, 0, 0, 500_000_000, time.UTC)
81		effective := sampled.Add(1) // 晚一纳秒
82		writeDiskFile(t, dir, diskState{
83			Points: openPoints(),
84			Samples: map[string]*Sample{
85				"S1": {
86					ID: "S1", PointID: "P1", SampledAt: sampled,
87					Measurements: []Measurement{{Item: openTurb, Value: 4}},
88					Status:       StatusConfirmed, Exceeded: false,
89					Results: []ItemResult{
90						{Item: openTurb, Value: 4, Limit: 5, LimitEffective: effective, Exceeded: false},
91					},
92				},
93			},
94		})
95		assertOpenRejectsEffective(t, dir, "S1", openTurb,
96			[]string{"晚于采样时间", "2026-09-10T12:00:00.500000001Z", "2026-09-10T12:00:00.5Z"},
97			nil)
98	}
99	
100	// 生效时间恰好等于采样时间可以接受：确认时“恰好生效”即选用该版，保存的依据同理。
101	func TestOpenLimitEffectiveExactlyAtSampling(t *testing.T) {
102		dir := t.TempDir()
103		sampled := time.Date(2026, 9, 10, 12, 0, 0, 500_000_000, time.UTC)
104		writeDiskFile(t, dir, diskState{
105			Points: openPoints(),
106			Samples: map[string]*Sample{
107				"S1": {
108					ID: "S1", PointID: "P1", SampledAt: sampled,
109					Measurements: []Measurement{{Item: openTurb, Value: 4}},
110					Status:       StatusConfirmed, Exceeded: false,
111					Results: []ItemResult{
112						{Item: openTurb, Value: 4, Limit: 5, LimitEffective: sampled, Exceeded: false},
113					},
114				},
115			},
116		})
117		s, err := Open(dir)
118		if err != nil {
119			t.Fatalf("生效时间恰好等于采样时间应正常读入: %v", err)
120		}
121		defer s.Close()
122		latest, ok, err := s.LatestResult("P1")
123		if err != nil || !ok || latest.ID != "S1" {
124			t.Fatalf("最近有效结果应指向 S1: %+v ok=%v err=%v", latest, ok, err)
125		}
126		r := latest.Results[0]
127		if r.Limit != 5 || !r.LimitEffective.Equal(sampled) || r.Exceeded {
128			t.Fatalf("判定依据应原样保留: %+v", r)
129		}
130	}
131	
132	// 不同时区的写法若代表同一时刻，按相等处理：生效时间用 +08:00 写法、采样时间用
133	// UTC 写法表示同一真实时刻（含小数秒），必须正常读入。
134	func TestOpenLimitEffectiveSameInstantDifferentZone(t *testing.T) {
135		dir := t.TempDir()
136		sampled := time.Date(2026, 9, 10, 12, 0, 0, 500_000_000, time.UTC)
137		beijing := time.FixedZone("CST", 8*3600)
138		effective := time.Date(2026, 9, 10, 20, 0, 0, 500_000_000, beijing)
139		if !effective.Equal(sampled) {
140			t.Fatal("测试前提：两种时区写法应表示同一真实时刻")
141		}
142		writeDiskFile(t, dir, diskState{
143			Points: openPoints(),
144			Samples: map[string]*Sample{
145				"S1": {
146					ID: "S1", PointID: "P1", SampledAt: sampled,
147					Measurements: []Measurement{{Item: openTurb, Value: 4}},
148					Status:       StatusConfirmed, Exceeded: false,
149					Results: []ItemResult{
150						{Item: openTurb, Value: 4, Limit: 5, LimitEffective: effective, Exceeded: false},
151					},
152				},
153			},
154		})
155		s, err := Open(dir)
156		if err != nil {
157			t.Fatalf("同一时刻的不同时区写法应按相等处理、正常读入: %v", err)
158		}
159		defer s.Close()
160		latest, ok, err := s.LatestResult("P1")
161		if err != nil || !ok || !latest.Results[0].LimitEffective.Equal(sampled) {
162			t.Fatalf("生效依据应原样保留: %+v ok=%v err=%v", latest, ok, err)
163		}
164	}
165	
166	// limitEffective 字段缺失、保存为 null 或落盘为 Go 零时间，都表示缺少生效依据，
167	// 不能当成一版很早的上限放行；三种写法共用“缺少上限生效时间”的拒绝信息，
168	// 与“晚于采样时间”相区分。直接写原始 JSON，因为 Go 结构体序列化总会带上该字段。
169	func TestOpenConfirmedLimitEffectiveMissing(t *testing.T) {
170		cases := []struct {
171			name           string
172			effectiveField string // 拼进判定记录的 limitEffective 字段文本
173		}{
174			{"字段缺失", ""},
175			{"保存为null", `"limitEffective": null,`},
176			{"Go零时间", `"limitEffective": "0001-01-01T00:00:00Z",`},
177		}
178		for _, c := range cases {
179			t.Run(c.name, func(t *testing.T) {
180				dir := t.TempDir()
181				raw := `{
182	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
183	  "samples": {
184	    "S1": {
185	      "id": "S1", "pointId": "P1",
186	      "sampledAt": "` + at(10, 0).Format(time.RFC3339Nano) + `",
187	      "measurements": [{"item": "浊度", "value": 4}],
188	      "status": "confirmed", "exceeded": false,
189	      "results": [{"item": "浊度", "value": 4, "limit": 5, ` + c.effectiveField + ` "exceeded": false}]
190	    }
191	  }
192	}`
193				if err := os.WriteFile(filepath.Join(dir, "water-data.json"), []byte(raw), 0o644); err != nil {
194					t.Fatalf("write data file: %v", err)
195				}
196				assertOpenRejectsEffective(t, dir, "S1", openTurb,
197					[]string{"缺少上限生效时间"},
198					[]string{"晚于采样时间"})
199			})
200		}
201	}
202	
203	// 已确认后作废、逐项依据仍保留的样品同样要过时间核对：作废只取消有效资格，
204	// 不能让采样之后才生效的上限借“历史记录”名义混入台账。
205	func TestOpenVoidedAfterConfirmedLimitEffectiveAfterSampling(t *testing.T) {
206		dir := t.TempDir()
207		writeDiskFile(t, dir, diskState{
208			Points: openPoints(),
209			Samples: map[string]*Sample{
210				"S1": {
211					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
212					Measurements: []Measurement{{Item: openTurb, Value: 4}},
213					Status:       StatusVoided, VoidReason: "复测确认样品污染", Exceeded: false,
214					Results: []ItemResult{
215						{Item: openTurb, Value: 4, Limit: 5, LimitEffective: at(11, 0), Exceeded: false},
216					},
217				},
218			},
219		})
220		assertOpenRejectsEffective(t, dir, "S1", openTurb,
221			[]string{"晚于采样时间"}, []string{"缺少上限生效时间"})
222	}
223	
224	// 多项目样品中只要一项的生效时间不符合，整次打开失败并点名该项目；
225	// 同文件中有其他正常样品也不能继续打开。
226	func TestOpenOneBadEffectiveTimeAmongManyRejectsWholeFile(t *testing.T) {
227		dir := t.TempDir()
228		writeDiskFile(t, dir, diskState{
229			Points: openPoints(),
230			Samples: map[string]*Sample{
231				// 完整、正常的已确认样品。
232				"S-GOOD": {
233					ID: "S-GOOD", PointID: "P1", SampledAt: at(5, 0),
234					Measurements: []Measurement{{Item: openPH, Value: 7}},
235					Status:       StatusConfirmed, Exceeded: false,
236					Results: []ItemResult{
237						{Item: openPH, Value: 7, Limit: 8, LimitEffective: openEff(), Exceeded: false},
238					},
239				},
240				// 双项目样品：pH 依据合法，浊度的上限生效时间晚于采样时间。
241				"S-BAD": {
242					ID: "S-BAD", PointID: "P1", SampledAt: at(10, 0),
243					Measurements: phTurbMeasurements(),
244					Status:       StatusConfirmed, Exceeded: true,
245					Results: []ItemResult{
246						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
247						{Item: openTurb, Value: 4, Limit: 5, LimitEffective: at(11, 0), Exceeded: false},
248					},
249				},
250			},
251		})
252		assertOpenRejectsEffective(t, dir, "S-BAD", openTurb,
253			[]string{"晚于采样时间"}, nil)
254	}
255	
256	// 核对只检查样品自己保存的生效依据，不要求它仍是当前登记版本中最新的一版：
257	// 后来补录了采样之前生效的新上限（若重算会改变结论），只要旧依据的生效时间
258	// 合法且其余完整性核对通过，旧结论仍原样读入。
259	func TestOpenOldBasisAcceptedDespiteBackfilledLimit(t *testing.T) {
260		dir := t.TempDir()
261		writeDiskFile(t, dir, diskState{
262			Points: openPoints(),
263			Limits: map[string][]Limit{
264				// 后来补录的、采样之前生效的更严上限：重算会把 4 判成超标。
265				diskLimitKey("P1", openTurb): {
266					{PointID: "P1", Item: openTurb, Value: 3, Effective: at(2, 0)},
267				},
268			},
269			Samples: map[string]*Sample{
270				"S1": {
271					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
272					Measurements: []Measurement{{Item: openTurb, Value: 4}},
273					Status:       StatusConfirmed, Exceeded: false,
274					Results: []ItemResult{
275						// 保存的旧依据：上限 5、采样前生效、4 <= 5 达标，自身完全合法。
276						{Item: openTurb, Value: 4, Limit: 5, LimitEffective: openEff(), Exceeded: false},
277					},
278				},
279			},
280		})
281		s, err := Open(dir)
282		if err != nil {
283			t.Fatalf("旧依据生效时间合法时应原样读入，不按补录限值重算: %v", err)
284		}
285		defer s.Close()
286		latest, ok, err := s.LatestResult("P1")
287		if err != nil || !ok || latest.ID != "S1" {
288			t.Fatalf("最近有效结果应指向 S1: %+v ok=%v err=%v", latest, ok, err)
289		}
290		r := latest.Results[0]
291		if r.Value != 4 || r.Limit != 5 || !r.LimitEffective.Equal(openEff()) || r.Exceeded || latest.Exceeded {
292			t.Fatalf("旧上限、生效时间与达标结论必须原样保留: %+v exceeded=%v", r, latest.Exceeded)
293		}
294	}
295	
296	// 没有逐项判定的待判定样品及直接作废的样品照常打开，不为它们补造上限或结论；
297	// 已作废样品继续仅供历史核对，不成为最近有效结果。
298	func TestOpenPendingAndDirectVoidedNotCheckedForEffectiveTime(t *testing.T) {
299		dir := t.TempDir()
300		writeDiskFile(t, dir, diskState{
301			Points: openPoints(),
302			Samples: map[string]*Sample{
303				"SP": {
304					ID: "SP", PointID: "P1", SampledAt: at(10, 0),
305					Measurements: []Measurement{{Item: openTurb, Value: 4}},
306					Status:       StatusPending,
307				},
308				"SV": {
309					ID: "SV", PointID: "P1", SampledAt: at(11, 0),
310					Measurements: []Measurement{{Item: openTurb, Value: 4}},
311					Status:       StatusVoided, VoidReason: "录入信息有误",
312				},
313			},
314		})
315		s, err := Open(dir)
316		if err != nil {
317			t.Fatalf("无逐项判定的待判定与直接作废样品应照常打开: %v", err)
318		}
319		defer s.Close()
320		list, err := s.ListByPoint("P1")
321		if err != nil || len(list) != 2 {
322			t.Fatalf("ListByPoint: %+v err=%v", list, err)
323		}
324		for _, smp := range list {
325			if len(smp.Results) != 0 || smp.Exceeded {
326				t.Fatalf("不应为 %s 补造上限或结论: %+v", smp.ID, smp)
327			}
328		}
329		if latest, ok, err := s.LatestResult("P1"); err != nil || ok {
330			t.Fatalf("待判定与直接作废样品不应成为最近有效结果: %+v ok=%v err=%v", latest, ok, err)
331		}
332	}
333	
334	// 打开因生效时间核对失败时不得改动原文件（assertOpenRejects 已逐字节核对），
335	// 这里再确认失败之后用合法依据覆盖重写可以正常打开，证明拒绝只发生在读取核对，
336	// 没有留下任何内部状态。
337	func TestOpenEffectiveTimeRejectionLeavesNoState(t *testing.T) {
338		dir := t.TempDir()
339		bad := diskState{
340			Points: openPoints(),
341			Samples: map[string]*Sample{
342				"S1": {
343					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
344					Measurements: []Measurement{{Item: openTurb, Value: 4}},
345					Status:       StatusConfirmed, Exceeded: false,
346					Results: []ItemResult{
347						{Item: openTurb, Value: 4, Limit: 5, LimitEffective: at(11, 0), Exceeded: false},
348					},
349				},
350			},
351		}
352		writeDiskFile(t, dir, bad)
353		if got, err := Open(dir); !errors.Is(err, ErrCorruptRecord) || got != nil {
354			t.Fatalf("生效时间晚于采样时间必须拒绝, got=%v err=%v", got, err)
355		}
356		good := bad
357		good.Samples["S1"].Results[0].LimitEffective = openEff()
358		writeDiskFile(t, dir, good)
359		s, err := Open(dir)
360		if err != nil {
361			t.Fatalf("修正为合法依据后应正常打开: %v", err)
362		}
363		defer s.Close()
364	}
