194	// 互相遮盖；这里固定生效时间核对在前，保证错误信息明确指向缺日期。
195	func TestOpenLimitMissingEffectiveAndValueReportsEffective(t *testing.T) {
196		dir := t.TempDir()
197		raw := `{
198	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
199	  "limits": {"P1-pH": [{"pointId": "P1", "item": "pH"}]}
200	}`
201		writeRawDiskFile(t, dir, raw)
202		assertOpenRejectsLimitEffective(t, dir, "P1", openPH)
203	}
204	
205	// 两版限值都缺少生效时间时，它们的零时间虽彼此相等，也不能被版本重复核对
206	// 抢先报成 ErrDuplicateLimitTime：根本问题是两版都没有写明生效时间，
207	// 必须按 ErrCorruptRecord 拒绝。
208	func TestOpenTwoVersionsMissingEffectiveAreCorruptNotDuplicate(t *testing.T) {
209		dir := t.TempDir()
210		raw := `{
211	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
212	  "limits": {"P1-pH": [
213	    {"pointId": "P1", "item": "pH", "value": 7},
214	    {"pointId": "P1", "item": "pH", "value": 8}
215	  ]}
216	}`
217		writeRawDiskFile(t, dir, raw)
218		got, err := Open(dir)
219		if got != nil {
220			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
221		}
222		if !errors.Is(err, ErrCorruptRecord) {
223			t.Fatalf("两版都缺生效时间应报 ErrCorruptRecord，got %v", err)
224		}
225		if errors.Is(err, ErrDuplicateLimitTime) {
226			t.Fatalf("缺生效时间不应被报成重复版本，got %v", err)
227		}
228	}
229	
230	// 已确认与已确认后作废样品保留自己的历史判定依据，坏限值不借它们“用过”或
231	// “没用过”的名义放行：只要文件里实际有一版限值缺日期，整次打开照样失败，
232	// 也不重算或改写任何历史结论。
233	func TestOpenLimitMissingEffectiveWithConfirmedAndVoidedSamples(t *testing.T) {
234		dir := t.TempDir()
235		raw := `{
236	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
237	  "limits": {"P1-COD": [{"pointId": "P1", "item": "COD", "value": 30}]},
238	  "samples": {
239	    "SC": {
240	      "id": "SC", "pointId": "P1",
241	      "sampledAt": "` + at(5, 0).Format(time.RFC3339Nano) + `",
242	      "measurements": [{"item": "pH", "value": 9}],
243	      "status": "confirmed", "exceeded": true,
244	      "results": [{"item": "pH", "value": 9, "limit": 8, "limitEffective": "` +
245			openEff().Format(time.RFC3339Nano) + `", "exceeded": true}]
246	    },
247	    "SV": {
248	      "id": "SV", "pointId": "P1",
249	      "sampledAt": "` + at(6, 0).Format(time.RFC3339Nano) + `",
250	      "measurements": [{"item": "pH", "value": 9}],
251	      "status": "voided", "voidReason": "复测确认样品污染", "exceeded": true,
252	      "results": [{"item": "pH", "value": 9, "limit": 8, "limitEffective": "` +
253			openEff().Format(time.RFC3339Nano) + `", "exceeded": true}]
254	    }
255	  }
256	}`
257		writeRawDiskFile(t, dir, raw)
258		assertOpenRejectsLimitEffective(t, dir, "P1", "COD")
259	}
260	
261	// 打开因限值缺生效时间失败后不留下任何内部状态：给这版限值补上生效时间覆盖
262	// 写回，同一目录即可正常打开，原有样品照常可见。
263	func TestOpenLimitMissingEffectiveRejectionLeavesNoState(t *testing.T) {
264		dir := t.TempDir()
265		bad := `{
266	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
267	  "limits": {"P1-pH": [{"pointId": "P1", "item": "pH", "value": 8}]},
268	  "samples": {
269	    "S1": {
270	      "id": "S1", "pointId": "P1",
271	      "sampledAt": "` + at(10, 0).Format(time.RFC3339Nano) + `",
272	      "measurements": [{"item": "pH", "value": 9}],
273	      "status": "pending"
274	    }
275	  }
276	}`
277		writeRawDiskFile(t, dir, bad)
278		if got, err := Open(dir); !errors.Is(err, ErrCorruptRecord) || got != nil {
279			t.Fatalf("缺少生效时间必须拒绝，got=%v err=%v", got, err)
280		}
281		good := `{
282	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
283	  "limits": {"P1-pH": [{"pointId": "P1", "item": "pH", "value": 8, "effective": "` +
284			openEff().Format(time.RFC3339Nano) + `"}]},
285	  "samples": {
286	    "S1": {
287	      "id": "S1", "pointId": "P1",
288	      "sampledAt": "` + at(10, 0).Format(time.RFC3339Nano) + `",
289	      "measurements": [{"item": "pH", "value": 9}],
290	      "status": "pending"
291	    }
292	  }
293	}`
294		writeRawDiskFile(t, dir, good)
295		s, err := Open(dir)
296		if err != nil {
297			t.Fatalf("补回生效时间后应正常打开: %v", err)
298		}
299		defer s.Close()
300		conf, err := s.Confirm("S1")
301		if err != nil {
302			t.Fatalf("补回生效时间后应能正常确认: %v", err)
303		}
304		if r := conf.Results[0]; r.Limit != 8 || !r.LimitEffective.Equal(openEff()) || !r.Exceeded {
305			t.Fatalf("应按补回的限值完成确认: %+v", r)
306		}
307	}
308	
309	// 生效时间完整的未来版本不是损坏：即使打开时尚未到生效时刻也照常读入，
310	// 确认时仍只选采样当时已生效的最近一版。
311	func TestOpenFutureLimitVersionWithCompleteEffectiveAccepted(t *testing.T) {
312		dir := t.TempDir()
313		writeDiskFile(t, dir, diskState{
314			Points: openPoints(),
315			Limits: map[string][]Limit{
316				diskLimitKey("P1", openPH): {
317					{PointID: "P1", Item: openPH, Value: 8, Effective: at(1, 0)},
318					{PointID: "P1", Item: openPH, Value: 6, Effective: at(20, 0)},
319				},
320			},
321			Samples: map[string]*Sample{
322				"S1": {
323					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
324					Measurements: []Measurement{{Item: openPH, Value: 7}},
325					Status:       StatusPending,
326				},
327			},
328		})
329		s, err := Open(dir)
330		if err != nil {
331			t.Fatalf("日期完整的未来版本应正常读入，不能因尚未生效当成损坏: %v", err)
332		}
333		defer s.Close()
334		conf, err := s.Confirm("S1")
335		if err != nil {
336			t.Fatalf("Confirm: %v", err)
337		}
338		// 采样当时未来版本尚未生效，仍取 9/1 的 8，7 ≤ 8 达标。
339		if r := conf.Results[0]; r.Limit != 8 || !r.LimitEffective.Equal(at(1, 0)) || r.Exceeded {
340			t.Fatalf("确认时应选采样当时已生效的最近一版: %+v", r)
341		}
342	}
343	
344	// 没有登记限值且其余数据完整的目录照常打开，已有待判定样品缺少适用上限时
345	// 继续按原规则在确认时拒绝，不受这条限值核对影响。
346	func TestOpenNoLimitsAndMissingApplicableLimitUnchanged(t *testing.T) {
347		dir := t.TempDir()
348		writeDiskFile(t, dir, diskState{
349			Points: openPoints(),
350			Samples: map[string]*Sample{
351				"S1": {
352					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
353					Measurements: []Measurement{{Item: openPH, Value: 7}},
354					Status:       StatusPending,
355				},
356			},
357		})
358		s, err := Open(dir)
359		if err != nil {
360			t.Fatalf("没有登记限值的完整数据应正常打开: %v", err)
361		}
362		defer s.Close()
363		if _, err := s.Confirm("S1"); !errors.Is(err, ErrMissingLimit) {
364			t.Fatalf("缺少适用上限仍应在确认时拒绝，got %v", err)
365		}
366	}
