373	// 后来新增或补录的限值即使会改变重新判定的结果，也不能据此拒绝完整记录，
374	// 更不能在打开时重算结论：已保存的上限、生效时间与超标结论保持原样。
375	func TestOpenCompleteRecordUnaffectedByNewerLimits(t *testing.T) {
376		s, dir := open(t)
377		mustPoint(t, s, "P1", "一号取水口")
378		mustLimit(t, s, "P1", openPH, 8.0, openEff())
379		mustSample(t, s, "S1", "P1", at(10, 0), Measurement{Item: openPH, Value: 9})
380		conf, err := s.Confirm("S1")
381		if err != nil || !conf.Exceeded || conf.Results[0].Limit != 8.0 {
382			t.Fatalf("setup: 9 > 8 应超标: %+v err=%v", conf, err)
383		}
384		if err := s.Close(); err != nil {
385			t.Fatalf("Close: %v", err)
386		}
387	
388		// 补录一版采样时刻之后才生效、更宽松的限值；再补一版采样之前生效的
389		// 宽松限值（若重算就会变成达标）。
390		s2, err := Open(dir)
391		if err != nil {
392			t.Fatalf("reopen for backfill: %v", err)
393		}
394		mustLimit(t, s2, "P1", openPH, 100.0, at(15, 0))
395		mustLimit(t, s2, "P1", openPH, 100.0, at(2, 0))
396		if err := s2.Close(); err != nil {
397			t.Fatalf("Close s2: %v", err)
398		}
399	
400		// 重新打开：完整记录不被新限值拒绝，结论仍是保存时的 8@09-01、超标。
401		s3, err := Open(dir)
402		if err != nil {
403			t.Fatalf("含新增限值时重新打开完整记录不应失败: %v", err)
404		}
405		defer s3.Close()
406		latest, ok, err := s3.LatestResult("P1")
407		if err != nil || !ok {
408			t.Fatalf("最近有效结果: %+v ok=%v err=%v", latest, ok, err)
409		}
410		if !latest.Exceeded || len(latest.Results) != 1 {
411			t.Fatalf("整份结论被重算: %+v", latest)
412		}
413		r := latest.Results[0]
414		if r.Value != 9 || r.Limit != 8.0 || !r.LimitEffective.Equal(openEff()) || !r.Exceeded {
415			t.Fatalf("已保存依据必须原样保留，不能按新限值重算: %+v", r)
416		}
417	}
