				Status:       StatusVoided, VoidReason: "复测确认样品污染", Exceeded: false,
				Results: []ItemResult{
					{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: false},
				},
			},
		},
	})
	assertOpenRejects(t, dir, "S1", openPH, false)
}

// 已确认后作废的样品单项都对、整份标记反了：同样整次拒绝并说明与逐项结论不一致。
